// Temporary in-memory observation of genuine engine frames; never attached to the prefab.
using System;using System.IO;using System.Linq;using System.Collections.Generic;
using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using Newtonsoft.Json;
public static class EnergyClusterLiveQA {
 static string Out=>Path.Combine(Directory.GetParent(Application.dataPath).FullName,"VFXWork/Previews/EnergyCluster/V6");
 static GameObject clone;static ParticleSystem[] systems;static List<object> samples=new List<object>();static int stage,frame=-1,shots,drained,restored,reused;static double begin;static bool background;static EditorWindow focused;
 static object State(ParticleSystem p){var a=new ParticleSystem.Particle[1];int n=p.GetParticles(a);return new{p.name,p.time,count=n,age=n>0?a[0].startLifetime-a[0].remainingLifetime:-1,emission=p.emission.enabled};}
 static void Sample(string label){samples.Add(new{label,frame=Time.frameCount,time=Time.timeAsDouble,systems=systems.Select(State).ToArray()});}
 static void Capture(string name){var cg=new GameObject("EnergyCluster_LiveCapture");RenderTexture rt=null;var previous=RenderTexture.active;try{var cam=cg.AddComponent<Camera>();cam.transform.position=new Vector3(0,0,-10);cam.orthographic=true;cam.orthographicSize=1.28f;cam.clearFlags=CameraClearFlags.SolidColor;cam.backgroundColor=new Color(5/255f,7/255f,22/255f,1);cam.cullingMask=1<<31;cam.allowHDR=false;cam.allowMSAA=false;rt=new RenderTexture(512,512,24,RenderTextureFormat.ARGB32);rt.Create();cam.targetTexture=rt;cam.Render();RenderTexture.active=rt;var t=new Texture2D(512,512,TextureFormat.RGBA32,false);t.ReadPixels(new Rect(0,0,512,512),0,0);t.Apply();File.WriteAllBytes(Path.Combine(Out,name+".png"),t.EncodeToPNG());UnityEngine.Object.Destroy(t);}finally{RenderTexture.active=previous;if(rt!=null){rt.Release();UnityEngine.Object.Destroy(rt);}UnityEngine.Object.Destroy(cg);}}
 static void Finish(string error=null){EditorApplication.update-=Tick;if(clone!=null)UnityEngine.Object.Destroy(clone);Application.runInBackground=background;if(focused!=null)focused.Focus();File.WriteAllText(Path.Combine(Out,"LivePlayback.json"),JsonConvert.SerializeObject(new{success=error==null&&drained==0&&restored>=5&&reused>=5,error,method="Actual Play Mode / native engine frames and particle ages. No Simulate, Emit, SetParticles or runtime component. Native Emission drain/restore, Stop/Play, disable/enable and offscreen return.",drained,restored,reused,samples,settingsRestored=true},Formatting.Indented));}
 static void Tick(){try{if(!Application.isPlaying){Finish("Stopped externally");return;}if(Time.frameCount==frame)return;frame=Time.frameCount;double elapsed=Time.timeAsDouble-begin;
  if(stage==0){if(elapsed>.12&&shots==0){Sample("live_early");Capture("Live_Early");shots++;}else if(elapsed>.29&&shots==1){Sample("live_late");Capture("Live_Late");shots++;}if(elapsed>.7){Sample("looping");foreach(var p in systems){var e=p.emission;e.enabled=false;}stage=1;begin=Time.timeAsDouble;}}
  else if(stage==1&&elapsed>.65){drained=systems.Sum(p=>p.particleCount);Sample("emission_drained");foreach(var p in systems){var e=p.emission;e.enabled=true;}stage=2;begin=Time.timeAsDouble;}
  else if(stage==2&&elapsed>.65){restored=systems.Sum(p=>p.particleCount);Sample("emission_restored");foreach(var p in systems){p.Stop(false,ParticleSystemStopBehavior.StopEmittingAndClear);p.Play(false);}stage=3;begin=Time.timeAsDouble;}
  else if(stage==3&&elapsed>.15){Sample("native_restart");clone.SetActive(false);stage=4;begin=Time.timeAsDouble;}
  else if(stage==4&&elapsed>.15){clone.SetActive(true);stage=5;begin=Time.timeAsDouble;}
  else if(stage==5&&elapsed>.15){reused=systems.Sum(p=>p.particleCount);Sample("root_reuse");clone.transform.position=Vector3.right*100;stage=6;begin=Time.timeAsDouble;}
  else if(stage==6&&elapsed>.2){clone.transform.position=Vector3.zero;Sample("offscreen_return");Finish();}
 }catch(Exception e){Finish(e.ToString());}}
 public static string Run(){if(!Application.isPlaying||Application.dataPath!="/Users/user/Desktop/VFXDemo/VFXDemo/Assets"||SceneManager.GetActiveScene().path!="Assets/Scenes/VFXWorkbench.unity")throw new Exception("Wrong target/state.");background=Application.runInBackground;Application.runInBackground=true;focused=EditorWindow.focusedWindow;EditorWindow.GetWindow(typeof(Editor).Assembly.GetType("UnityEditor.GameView")).Focus();clone=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/PixelFX/EnergyCluster/Prefabs/VFX_EnergyCluster_Loop.prefab"));clone.name="EnergyCluster_QA_Temporary";foreach(var t in clone.GetComponentsInChildren<Transform>())t.gameObject.layer=31;systems=clone.GetComponentsInChildren<ParticleSystem>();foreach(var p in systems){p.Stop(false,ParticleSystemStopBehavior.StopEmittingAndClear);p.Play(false);}begin=Time.timeAsDouble;EditorApplication.update+=Tick;return "Native live playback verification started (~3 engine seconds).";}
}
